INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'cy-b2g-central-2019', id, '2019-04-18', 1, 'https://ec.europa.eu/digital-building-blocks/sites/display/DIGITAL/eInvoicing+in+Cyprus', 0, '[{"label": "EC — eInvoicing in Cyprus", "url": "https://ec.europa.eu/digital-building-blocks/sites/display/DIGITAL/eInvoicing+in+Cyprus"}]', NULL FROM countries WHERE code = 'CY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-central-2019', 'en', 'Central public bodies must receive EN 16931 e-invoices', 'Law 89(I)/2019 transposes EU Directive 2014/55/EU: all central public sector bodies must be able to receive and process electronic invoices compliant with the European Standard EN 16931. Issuance by suppliers remains voluntary — this is a receiving obligation for government bodies only.', '["Suppliers to Cypriot central government bodies may issue structured e-invoices voluntarily via Peppol or the government portal, though there is no requirement to do so"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'cy-b2g-subcentral-2020', id, '2020-04-18', 0, 'https://sovos.com/vat/tax-rules/cyprus-e-invoicing/', 1, '[{"label": "EC — eInvoicing in Cyprus", "url": "https://ec.europa.eu/digital-building-blocks/sites/display/DIGITAL/eInvoicing+in+Cyprus"}]', NULL FROM countries WHERE code = 'CY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-b2g-subcentral-2020', 'en', 'Sub-central public bodies must also receive e-invoices', 'The receiving obligation extends to all remaining public sector bodies — regional and local authorities beyond the central government entities already covered since 2019 — completing Cyprus''s rollout of Directive 2014/55/EU. Issuance remains voluntary throughout; a 1 January 2022 target to make issuance mandatory was discussed by the Ministry of Finance but never enacted, and a similar 2024 target was also postponed.', '["Confirm whether the specific public body you invoice is a central or sub-central entity — both are now required to accept compliant e-invoices, though neither requires you to send one"]');

INSERT OR IGNORE INTO milestones (id, country_id, date, anchor, source_url, on_tracker, portals, confidence) SELECT 'cy-vida-2030', id, '2030-07-01', 0, 'https://taxation-customs.ec.europa.eu/taxation/vat/vat-digital-age-vida_en', 1, '[{"label": "EC — eInvoicing in Cyprus", "url": "https://ec.europa.eu/digital-building-blocks/sites/display/DIGITAL/eInvoicing+in+Cyprus"}]', NULL FROM countries WHERE code = 'CY';
INSERT OR IGNORE INTO milestone_translations (milestone_id, lang, system, desc, actions) VALUES ('cy-vida-2030', 'en', 'ViDA cross-border B2B digital reporting takes effect', 'Regardless of whether Cyprus ever enacts its own domestic B2B or B2G-issuance mandate, the EU''s VAT in the Digital Age (ViDA) directive requires structured e-invoicing and digital reporting for intra-Community B2B transactions from 1 July 2030 — confirmed EU law (Council Directive (EU) 2025/516).', '["Businesses trading cross-border within the EU should plan for EN 16931-compliant e-invoicing and reporting capability by this date, independent of any domestic Cypriot mandate"]');
